  const int nthreads = blockDim.x;
  const bool use_vec = (N & 3LL) == 0LL;
  const long long nvec = use_vec ? (N >> 2) : 0LL;
  const long long tail_begin = use_vec ? (nvec << 2) : 0LL;
  __shared__ double ssum[1024];
  __shared__ double ssq[1024];
  __shared__ float smean;
  __shared__ float srstd;
