    for (int s = nthreads >> 1; s > 0; s >>= 1) {
      if (tid < s) {
        ssum[tid] += ssum[tid + s];
        ssq[tid] += ssq[tid + s];
      }
      __syncthreads();
    }
    if (tid == 0) {
      const double mean = ssum[0] / (double)N;
      double var = ssq[0] / (double)N - mean * mean;
      if (var < 0.0) var = 0.0;
      smean = (float)mean;
      srstd = rsqrtf((float)var + eps);
