    for (long long i = tail_begin + tid; i < N; i += nthreads) {
      yrow[i] = (xrow[i] - mean) * rstd * w[i] + b[i];
    }
    // Ensure all threads are done reading smean/srstd before the next
    // grid-stride iteration overwrites the shared reduction buffers.
    __syncthreads();
  }
}

